"Insurance appraisal","Appraisal clause","Property claim valuation","Snow load damage","Earthquake claims","Remote construction costs"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://alaskainsuranceappraiser.com/#website","url":"https://alaskainsuranceappraiser.com/","name":"Alaska Insurance Appraiser","publisher":{"@id":"https://alaskainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#webpage","url":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/","name":"Insurance Claim Glossary | ACV, RCV, Umpire & More","description":"Plain-English definitions of insurance claim terms: actual cash value, holdback, appraisal award, umpire, snow load, borough and more.","inLanguage":"en-US","isPartOf":{"@id":"https://alaskainsuranceappraiser.com/#website"},"about":{"@id":"https://alaskainsuranceappraiser.com/#business"},"publisher":{"@id":"https://alaskainsuranceappraiser.com/#business"},"dateModified":"2026-11-13","primaryImageOfPage":{"@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#primaryimage"},"breadcrumb":{"@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#breadcrumb"},"mainEntity":{"@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#definedtermset"}},{"@type":"ImageObject","@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#primaryimage","url":"https://alaskainsuranceappraiser.com/assets/img/photos/calculator-documents.webp","contentUrl":"https://alaskainsuranceappraiser.com/assets/img/photos/calculator-documents.webp","width":1200,"height":800,"caption":"Calculator resting on printed charts beside a laptop keyboard"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://alaskainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/"}],"@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Often the first payment on a replacement cost policy."},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is being repaired after a covered loss."},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either side demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side appoints to value the loss. Policies often require appraisers to be competent and independent."},{"@type":"DefinedTerm","name":"Arctic entry","description":"An enclosed entry vestibule common in Alaska homes that limits heat loss. It is part of the dwelling for claim purposes."},{"@type":"DefinedTerm","name":"Barge freight","description":"Shipping materials by barge to coastal or river communities, often on a seasonal schedule. A real cost in remote repairs."},{"@type":"DefinedTerm","name":"Borough","description":"Alaska's equivalent of a county. The state has 19 organized boroughs plus the Unorganized Borough."},{"@type":"DefinedTerm","name":"Census area","description":"One of 11 statistical divisions of Alaska's Unorganized Borough, used where no borough government exists."},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage for the house itself and attached structures."},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage for detached garages, shops, sheds and fences."},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for contents."},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of your policy listing coverages, limits, deductibles and endorsements."},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss you pay before the policy pays."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, used to calculate actual cash value."},{"@type":"DefinedTerm","name":"Earth movement exclusion","description":"A common exclusion for earthquake, landslide, settlement and similar ground movement."},{"@type":"DefinedTerm","name":"Earthquake endorsement","description":"An addition to a policy that provides earthquake coverage, usually with a percentage deductible."},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage."},{"@type":"DefinedTerm","name":"Estimate","description":"An itemized list of the work and materials needed to repair a loss, with quantities and prices."},{"@type":"DefinedTerm","name":"Glacial outburst flood","description":"A sudden release of water dammed by or beside a glacier, such as the floods on Juneau's Mendenhall River."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld until repairs are complete."},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can then leak into the home."},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering roof membrane installed in vulnerable areas such as eaves and valleys to resist leaks."},{"@type":"DefinedTerm","name":"Line item","description":"A single entry on an estimate, such as a quantity of drywall or roofing at a unit price."},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether repaired areas must reasonably match undamaged areas, which can expand the scope."},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps taken to prevent further damage, such as tarping, drying, heating or snow removal."},{"@type":"DefinedTerm","name":"Named peril","description":"A cause of loss specifically listed as covered in a policy."},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of meeting current building codes when repairing a damaged building."},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor's charges for managing a project, often expressed as percentages."},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of a coverage limit rather than a flat dollar amount."},{"@type":"DefinedTerm","name":"Permafrost","description":"Ground that stays frozen for two or more years. Thaw-related settlement is usually excluded from coverage."},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which the insurer may request within a set time."},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional who represents a policyholder in presenting and negotiating a claim."},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the policy will pay once repairs or replacement are completed."},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace with new materials of like kind and quality, without deduction for depreciation."},{"@type":"DefinedTerm","name":"Scope of loss","description":"The full description of the damaged areas and items, and the work needed to repair them."},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of accumulated snow and ice on a roof, measured in pounds per square foot."},{"@type":"DefinedTerm","name":"Steep charge","description":"An additional cost for working on steep roofs, typically above a certain pitch."},{"@type":"DefinedTerm","name":"Suit limitation clause","description":"The policy condition limiting how long you have to file a lawsuit against the insurer."},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missed or underpaid in the original estimate."},{"@type":"DefinedTerm","name":"Surplus lines","description":"Insurance written by insurers not licensed in the state, used for risks the standard market does not cover."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers cannot agree on."},{"@type":"DefinedTerm","name":"Unorganized Borough","description":"The large part of Alaska not within an organized borough, divided into census areas for statistics."},{"@type":"DefinedTerm","name":"Weight of ice, snow or sleet","description":"A named peril in many homeowner policies covering damage caused by the weight of accumulated snow and ice."}],"@id":"https://alaskainsuranceappraiser.com/insurance-claim-glossary/#definedtermset"}]}</script>
</head>
